(window.__qhadithX=window.__qhadithX||{})[25]={"68":[{"c":"Sunan Abu Dawud","r":"Hadith 2317","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2317","x":"Ibn ‘Abbas said \"The verse concerning the payment of ransom stands valid for pregnant and sucking woman.\"","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا أَبَانُ، حَدَّثَنَا قَتَادَةُ، أَنَّ عِكْرِمَةَ، حَدَّثَهُ أَنَّ ابْنَ عَبَّاسٍ قَالَ أُثْبِتَتْ لِلْحُبْلَى وَالْمُرْضِعِ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 4285","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4285","x":"Narrated AbuSa'id al-Khudri:\n\nThe Prophet (ﷺ) said: The Mahdi will be of my stock, and will have a broad forehead a prominent nose. He will fill the earth will equity and justice as it was filled with oppression and tyranny, and he will rule for seven years.","ar":"حَدَّثَنَا سَهْلُ بْنُ تَمَّامِ بْنِ بَزِيعٍ، حَدَّثَنَا عِمْرَانُ الْقَطَّانُ، عَنْ قَتَادَةَ، عَنْ أَبِي نَضْرَةَ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ الْمَهْدِيُّ مِنِّي أَجْلَى الْجَبْهَةِ أَقْنَى الأَنْفِ يَمْلأُ الأَرْضَ قِسْطًا وَعَدْلاً كَمَا مُلِئَتْ جَوْرًا وَظُلْمًا يَمْلِكُ سَبْعَ سِنِينَ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 4286","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4286","x":"Narrated Umm Salamah, Ummul Mu'minin:\n\nThe Prophet (ﷺ) said: Disagreement will occur at the death of a caliph and a man of the people of Medina will come flying forth to Mecca. Some of the people of Mecca will come to him, bring him out against his will and swear allegiance to him between the Corner and the Maqam. An expeditionary force will then be sent against him from Syria but will be swallowed up in the desert between Mecca and Medina. When the people see that, the eminent saints of Syria and the best people of Iraq will come to him and swear allegiance to him between the Corner and the Maqam. Then there will arise a man of Quraysh whose maternal uncles belong to Kalb and send against them an expeditionary force which will be overcome by them, and that is the expedition of Kalb. Disappointed will be the one who does not receive the booty of Kalb. He will divide the property, and will govern the people by the Sunnah of their Prophet (ﷺ) and establish Islam on Earth. He will remain seven years, then die, and the Muslims will pray over him. Abu Dawud said: Some transmitted from Hisham \"nine years\" and some \"seven years\".","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا مُعَاذُ بْنُ هِشَامٍ، حَدَّثَنِي أَبِي، عَنْ قَتَادَةَ، عَنْ صَالِحٍ أَبِي الْخَلِيلِ، عَنْ صَاحِبٍ، لَهُ عَنْ أُمِّ سَلَمَةَ، زَوْجِ النَّبِيِّ صلى الله عليه وسلم عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ يَكُونُ اخْتِلاَفٌ عِنْدَ مَوْتِ خَلِيفَةٍ فَيَخْرُجُ رَجُلٌ مِنْ أَهْلِ الْمَدِينَةِ هَارِبًا إِلَى مَكَّةَ فَيَأْتِيهِ نَاسٌ مِنْ أَهْلِ مَكَّةَ فَيُخْرِجُونَهُ وَهُوَ كَارِهٌ فَيُبَايِعُونَهُ بَيْنَ الرُّكْنِ وَالْمَقَامِ وَيُبْعَثُ إِلَيْهِ بَعْثٌ مِنَ الشَّامِ فَيُخْسَفُ بِهِمْ بِالْبَيْدَاءِ بَيْنَ مَكَّةَ وَالْمَدِينَةِ فَإِذَا رَأَى النَّاسُ ذَلِكَ أَتَاهُ أَبْدَالُ الشَّامِ وَعَصَائِبُ أَهْلِ الْعِرَاقِ فَيُبَايِعُونَهُ بَيْنَ الرُّكْنِ وَالْمَقَامِ ثُمَّ يَنْشَأُ رَجُلٌ مِنْ قُرَيْشٍ أَخْوَالُهُ كَلْبٌ فَيَبْعَثُ إِلَيْهِمْ بَعْثًا فَيَظْهَرُونَ عَلَيْهِمْ وَذَلِكَ بَعْثُ كَلْبٍ وَالْخَيْبَةُ لِمَنْ لَمْ يَشْهَدْ غَنِيمَةَ كَلْبٍ فَيَقْسِمُ الْمَالَ وَيَعْمَلُ فِي النَّاسِ بِسُنَّةِ نَبِيِّهِمْ صلى الله عليه وسلم وَيُلْقِي الإِسْلاَمُ بِجِرَانِهِ إِلَى الأَرْضِ فَيَلْبَثُ سَبْعَ سِنِينَ ثُمَّ يُتَوَفَّى وَيُصَلِّي عَلَيْهِ الْمُسْلِمُونَ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ قَالَ بَعْضُهُمْ عَنْ هِشَامٍ ‏\"‏ تِسْعَ سِنِينَ ‏\"‏ ‏.‏ وَقَالَ بَعْضُهُمْ ‏\"‏ سَبْعَ سِنِينَ ‏\"‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3855","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3855","x":"Narrated Sa`id bin Jubair:\n\n`AbdurRahman bin Abza said, \"Ask Ibn `Abbas about these two Qur'anic Verses: 'Nor kill such life as Allah has made sacred, Except for just cause.' (25.68) \"And whoever kills a believer intentionally, his recompense is Hell. (4.93) So I asked Ibn `Abbas who said, \"When the Verse that is in Sura-al-Furqan was revealed, the pagans of Mecca said, 'But we have slain such life as Allah has made sacred, and we have invoked other gods along with Allah, and we have also committed fornication.' So Allah revealed:-- 'Except those who repent, believe, and do good-- (25.70) So this Verse was concerned with those people. As for the Verse in Surat-an-Nisa (4-93), it means that if a man, after understanding Islam and its laws and obligations, murders somebody, then his punishment is to dwell in the (Hell) Fire forever.\" Then I mentioned this to Mujahid who said, \"Except the one who regrets (one's crime). \"","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، حَدَّثَنِي سَعِيدُ بْنُ جُبَيْرٍ، أَوْ قَالَ حَدَّثَنِي الْحَكَمُ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ أَمَرَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبْزَى قَالَ سَلِ ابْنَ عَبَّاسٍ عَنْ هَاتَيْنِ الآيَتَيْنِ، مَا أَمْرُهُمَا ‏{‏وَلاَ تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ ‏}‏ ‏{‏وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا‏}‏ فَسَأَلْتُ ابْنَ عَبَّاسٍ فَقَالَ لَمَّا أُنْزِلَتِ الَّتِي فِي الْفُرْقَانِ قَالَ مُشْرِكُو أَهْلِ مَكَّةَ فَقَدْ قَتَلْنَا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ، وَدَعَوْنَا مَعَ اللَّهِ إِلَهًا آخَرَ، وَقَدْ أَتَيْنَا الْفَوَاحِشَ‏.‏ فَأَنْزَلَ اللَّهُ ‏{‏إِلاَّ مَنْ تَابَ وَآمَنَ‏}‏ الآيَةَ فَهَذِهِ لأُولَئِكَ وَأَمَّا الَّتِي فِي النِّسَاءِ الرَّجُلُ إِذَا عَرَفَ الإِسْلاَمَ وَشَرَائِعَهُ، ثُمَّ قَتَلَ فَجَزَاؤُهُ جَهَنَّمُ‏.‏ فَذَكَرْتُهُ لِمُجَاهِدٍ فَقَالَ إِلاَّ مَنْ نَدِمَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4761","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4761","x":"Narrated `Abdullah:\n\nI or somebody, asked Allah's Messenger (ﷺ) \"Which is the biggest sin in the Sight of Allah?\" He said, \"That you set up a rival (in worship) to Allah though He Alone created you.\" I asked, \"What is next?\" He said, \"Then, that you kill your son, being afraid that he may share your meals with you.\" I asked, \"What is next?\" He said, \"That you commit illegal sexual intercourse with the wife of your neighbor.\" Then the following Verse was revealed to confirm the statement of Allah's Messenger (ﷺ): \"Those who invoke not with Allah, any other god, nor kill life as Allah has forbidden except for just cause, nor commit illegal sexual intercourse.\" (25.68)","ar":"حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنْ سُفْيَانَ، قَالَ حَدَّثَنِي مَنْصُورٌ، وَسُلَيْمَانُ، عَنْ أَبِي وَائِلٍ، عَنْ أَبِي مَيْسَرَةَ، عَنْ عَبْدِ اللَّهِ،‏.‏ قَالَ وَحَدَّثَنِي وَاصِلٌ، عَنْ أَبِي وَائِلٍ، عَنْ عَبْدِ اللَّهِ ـ رضى الله عنه ـ قَالَ سَأَلْتُ ـ أَوْ سُئِلَ رَسُولُ اللَّهِ صلى الله عليه وسلم ـ أَىُّ الذَّنْبِ عِنْدَ اللَّهِ أَكْبَرُ قَالَ ‏\"‏ أَنْ تَجْعَلَ لِلَّهِ نِدًّا وَهْوَ خَلَقَكَ ‏\"‏‏.‏ قُلْتُ ثُمَّ أَىٌّ قَالَ ‏\"‏ ثُمَّ أَنْ تَقْتُلَ وَلَدَكَ خَشْيَةَ أَنْ يَطْعَمَ مَعَكَ‏\"‏‏.‏ قُلْتُ ثُمَّ أَىٌّ قَالَ ‏\"‏ أَنْ تُزَانِيَ بِحَلِيلَةِ جَارِكَ ‏\"‏‏.‏ قَالَ وَنَزَلَتْ هَذِهِ الآيَةُ تَصْدِيقًا لِقَوْلِ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏{‏وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَلَا يَزْنُونَ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4764","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4764","x":"Narrated Sa`id bin Jubair:\n\nI asked Ibn `Abbas about Allah's saying:-- '.. this reward is Hell Fire.' (4.93) He said, \"No repentance is accepted from him (i.e. the murderer of a believer).\" I asked him regarding the saying of Allah: 'Those who invoke not with Allah any other god.'...(25.68) He said, \"This Verse was revealed concerning the pagans of the pre-lslamic period.\"","ar":"حَدَّثَنَا آدَمُ، حَدَّثَنَا شُعْبَةُ، حَدَّثَنَا مَنْصُورٌ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ سَأَلْتُ ابْنَ عَبَّاسٍ ـ رضى الله عنهما ـ عَنْ قَوْلِهِ تَعَالَى ‏{‏فَجَزَاؤُهُ جَهَنَّمُ‏}‏ قَالَ لاَ تَوْبَةَ لَهُ‏.‏ وَعَنْ قَوْلِهِ جَلَّ ذِكْرُهُ ‏{‏لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ‏}‏ قَالَ كَانَتْ هَذِهِ فِي الْجَاهِلِيَّةِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4765","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4765","x":"Narrated Sa`id bin Jubair:\n\nIbn Abza said to me, \"Ask Ibn `Abbas regarding the Statement of Allah: 'And whoever murders a believer intentionally, his recompense is Hell.' (4.69) And also His Statement: '...nor kill such life as Allah has forbidden, except for a just cause.....except those who repent, believe, and do good deeds.' \" (25.68-70) So I asked Ibn `Abbas and he said, \"When this (25.68-69) was revealed, the people of Mecca said, \"We have invoked other gods with Allah, and we have murdered such lives which Allah has made sacred, and we have committed illegal sexual intercourse. So Allah revealed: 'Except those who repent, believe, and do good deeds and Allah is Oft-Forgiving, Most Merciful.' (25.70)","ar":"حَدَّثَنَا سَعْدُ بْنُ حَفْصٍ، حَدَّثَنَا شَيْبَانُ، عَنْ مَنْصُورٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ قَالَ ابْنُ أَبْزَى سَلِ ابْنَ عَبَّاسٍ عَنْ قَوْلِهِ تَعَالَى ‏{‏وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ‏}‏ وَقَوْلِهِ ‏{‏لاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ‏}‏ حَتَّى بَلَغَ ‏{‏إِلاَّ مَنْ تَابَ‏}‏ فَسَأَلْتُهُ فَقَالَ لَمَّا نَزَلَتْ قَالَ أَهْلُ مَكَّةَ فَقَدْ عَدَلْنَا بِاللَّهِ وَقَتَلْنَا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَأَتَيْنَا الْفَوَاحِشَ، فَأَنْزَلَ اللَّهُ ‏{‏إِلاَّ مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلاً صَالِحًا‏}‏ إِلَى قَوْلِهِ ‏{‏غَفُورًا رَحِيمًا‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4810","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4810","x":"Narrated Ibn `Abbas:\n\nSome pagans who committed murders in great number and committed illegal sexual intercourse excessively, came to Muhammad and said, \"O Muhammad! Whatever you say and invite people to, is good: but we wish if you could inform us whether we can make an expiration for our (past evil) deeds.\" So the Divine Verses came: 'Those who invoke not with Allah any other god, not kill such life as Allah has forbidden except for just cause, nor commit illegal sexual intercourse.' (25.68) And there was also revealed:-- 'Say: O My slaves who have transgressed against their souls! Despair not of the Mercy of Allah.' (39.53)","ar":"حَدَّثَنِي إِبْرَاهِيمُ بْنُ مُوسَى، أَخْبَرَنَا هِشَامُ بْنُ يُوسُفَ، أَنَّ ابْنَ جُرَيْجٍ، أَخْبَرَهُمْ قَالَ يَعْلَى إِنَّ سَعِيدَ بْنَ جُبَيْرٍ أَخْبَرَهُ عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ أَنَّ نَاسًا، مِنْ أَهْلِ الشِّرْكِ كَانُوا قَدْ قَتَلُوا وَأَكْثَرُوا وَزَنَوْا وَأَكْثَرُوا، فَأَتَوْا مُحَمَّدًا صلى الله عليه وسلم فَقَالُوا إِنَّ الَّذِي تَقُولُ وَتَدْعُو إِلَيْهِ لَحَسَنٌ لَوْ تُخْبِرُنَا أَنَّ لِمَا عَمِلْنَا كَفَّارَةً‏.‏ فَنَزَلَ ‏{‏وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَلاَ يَزْنُونَ‏}‏ وَنَزَلَ ‏{‏قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لاَ تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6001","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6001","x":"Narrated `Abdullah:\n\nI said 'O Allah's Messenger (ﷺ)! Which sin is the greatest?\" He said, \"To set up a rival unto Allah, though He Alone created you.\" I said, \"What next?\" He said, \"To kill your son lest he should share your food with you.\" I further asked, \"What next?\" He said, \"To commit illegal sexual intercourse with the wife of your neighbor.\" And then Allah revealed as proof of the statement of the Prophet: 'Those who invoke not with Allah any other god)................. (to end of verse)...' (25.68)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، أَخْبَرَنَا سُفْيَانُ، عَنْ مَنْصُورٍ، عَنْ أَبِي وَائِلٍ، عَنْ عَمْرِو بْنِ شُرَحْبِيلَ، عَنْ عَبْدِ اللَّهِ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أَىُّ الذَّنْبِ أَعْظَمُ قَالَ ‏\"‏ أَنْ تَجْعَلَ لِلَّهِ نِدًّا وَهْوَ خَلَقَكَ ‏\"‏‏.‏ ثُمَّ قَالَ أَىُّ قَالَ ‏\"‏ أَنْ تَقْتُلَ وَلَدَكَ خَشْيَةَ أَنْ يَأْكُلَ مَعَكَ ‏\"‏‏.‏ قَالَ ثُمَّ أَىُّ قَالَ ‏\"‏ أَنْ تُزَانِيَ حَلِيلَةَ جَارِكَ ‏\"‏‏.‏ وَأَنْزَلَ اللَّهُ تَصْدِيقَ قَوْلِ النَّبِيِّ صلى الله عليه وسلم ‏{‏وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6861","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6861","x":"Narrated `Abdullah:\n\nA man said, \"O Allah's Messenger (ﷺ)! Which sin is the greatest in Allah's Sight?\" The Prophet (ﷺ) said, \"To set up a rival unto Allah though He Alone created you. \" The man said, \"What is next?\" The Prophet (ﷺ) said, \"To kill your son lest he should share your food with you.\" The man said, \"What is next?\" The Prophet said, \"To commit illegal sexual intercourse with the wife of your neighbor.\" So Allah revealed in confirmation of this narration:-- 'And those who invoke not with Allah, any other god. Nor kill, such life as Allah has forbidden except for just cause nor commit illegal sexual intercourse. And whoever does this shall receive the punishment.' (25.68)","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي وَائِلٍ، عَنْ عَمْرِو بْنِ شُرَحْبِيلَ، قَالَ قَالَ عَبْدُ اللَّهِ قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَىُّ الذَّنْبِ أَكْبَرُ عِنْدَ اللَّهِ قَالَ ‏\"‏ أَنْ تَدْعُوَ لِلَّهِ نِدًّا، وَهْوَ خَلَقَكَ ‏\"‏‏.‏ قَالَ ثُمَّ أَىٌّ قَالَ ‏\"‏ ثُمَّ أَنْ تَقْتُلَ وَلَدَكَ، أَنْ يَطْعَمَ مَعَكَ ‏\"‏‏.‏ قَالَ ثُمَّ أَىٌّ قَالَ ‏\"‏ ثُمَّ أَنْ تُزَانِيَ بِحَلِيلَةِ جَارِكَ ‏\"‏‏.‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ تَصْدِيقَهَا ‏{‏وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَلاَ يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ‏ يَلْقَ أَثَامًا}‏ الآيَةَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 7532","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-7532","x":"Narrated `Abdullah:\n\nA man said, \"O Allah's Messenger (ﷺ)! Which sin is the biggest in Allah's Sight?\" The Prophet (ﷺ) said, \"To set up rivals unto Allah though He Alone created you.\" That man said, \"What is next?\" The Prophet (ﷺ) said, \"To kill your son lest he should share your food with you.'' The man said, \"What is next?\" The Prophet said, \"To commit illegal sexual intercourse with the wife of your neighbor.\" Then Allah revealed in confirmation of that: \"And those who invoke not with Allah any other god, nor kill such life as Allah has made sacred except for just cause, nor commit illegal sexual intercourse and whoever does this shall receive the punishment..... (25.68)","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي وَائِلٍ، عَنْ عَمْرِو بْنِ شُرَحْبِيلَ، قَالَ قَالَ عَبْدُ اللَّهِ قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَىُّ الذَّنْبِ أَكْبَرُ عِنْدَ اللَّهِ قَالَ ‏\"‏ أَنْ تَدْعُوَ لِلَّهِ نِدًّا، وَهْوَ خَلَقَكَ ‏\"‏‏.‏ قَالَ ثُمَّ أَىّ قَالَ ‏\"‏ ثُمَّ أَنْ تَقْتُلَ وَلَدَكَ، أَنْ يَطْعَمَ مَعَكَ ‏\"‏‏.‏ قَالَ ثُمَّ أَىّ قَالَ ‏\"‏ أَنْ تُزَانِيَ حَلِيلَةَ جَارِكَ ‏\"‏‏.‏ فَأَنْزَلَ اللَّهُ تَصْدِيقَهَا ‏{‏وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَلاَ يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ‏}‏ الآيَةَ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 86b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-86b","x":"It is narrated on the authority of Abdullah b. Mas'ud that a man said:\n\nMessenger of Allah, which offence is the most grievous in the eye of Allah? He (the Holy Prophet) replied: That you associate a partner with Allah (despite the fact) that He created you. He (the man) said: What next? He (the Holy Prophet) replied: That you kill your child out of fear that he would join you in food. He (the inquirer) said (again): What next? He (the Holy Prophet) replied: That you commit adultery with the wife of your neighbour. And the Almighty and Exalted Lord testified it (with this verse): All those who call not unto another god along with Allah, and slay not any soul which Allah has forbidden, except in the cause of justice, nor commit fornication, and he who does this shall meet a requital of sin (xxv. 68).","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ، جَمِيعًا عَنْ جَرِيرٍ، قَالَ عُثْمَانُ حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي وَائِلٍ، عَنْ عَمْرِو بْنِ شُرَحْبِيلَ، قَالَ قَالَ عَبْدُ اللَّهِ قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَىُّ الذَّنْبِ أَكْبَرُ عِنْدَ اللَّهِ قَالَ ‏\"‏ أَنْ تَدْعُوَ لِلَّهِ نِدًّا وَهُوَ خَلَقَكَ ‏\"‏ ‏.‏ قَالَ ثُمَّ أَىٌّ قَالَ ‏\"‏ أَنْ تَقْتُلَ وَلَدَكَ مَخَافَةَ أَنْ يَطْعَمَ مَعَكَ ‏\"‏ ‏.‏ قَالَ ثُمَّ أَىٌّ قَالَ ‏\"‏ أَنْ تُزَانِيَ حَلِيلَةَ جَارِكَ ‏\"‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ تَصْدِيقَهَا ‏{‏ وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَلاَ يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 122","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-122","x":"It is narrated on the authority of Ibn 'Abbas that some persons amongst the polytheist had committed a large number of murders and had excessively indulged in fornication. Then they came to Muhammad (ﷺ) and said:\n\nWhatever you assert and whatever you call to is indeed good. But if you inform us that there is atonement of our past deeds (then we would embrace Islam). Then it was revealed: And those who call not unto another god along with Allah and slay not any soul which Allah has forbidden except in the cause of justice, nor commit fornication; and he who does this shall meet the requital of sin. Multiplied for him shall be the torment on the Day of Resurrection, and he shall therein abide disgraced, except him who repents a believes and does good deeds. Then these! for the Allah shall change their vices into virtues. Verily Allah is Ever Forgiving, Merciful (xxv. 68-70). Say thou: O my bondsmen woo have committed extravagance against themselves despair not of the Mercy of Allah I Verily Allah will forgive the sins altogether. He is indeed the Forgiving, the Merciful (xxxix. 53).","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمِ بْنِ مَيْمُونٍ، وَإِبْرَاهِيمُ بْنُ دِينَارٍ، - وَاللَّفْظُ لإِبْرَاهِيمَ - قَالاَ حَدَّثَنَا حَجَّاجٌ، - وَهُوَ ابْنُ مُحَمَّدٍ - عَنِ ابْنِ جُرَيْجٍ، قَالَ أَخْبَرَنِي يَعْلَى بْنُ مُسْلِمٍ، أَنَّهُ سَمِعَ سَعِيدَ بْنَ جُبَيْرٍ، يُحَدِّثُ عَنِ ابْنِ عَبَّاسٍ، أَنَّ نَاسًا، مِنْ أَهْلِ الشِّرْكِ قَتَلُوا فَأَكْثَرُوا وَزَنَوْا فَأَكْثَرُوا ثُمَّ أَتَوْا مُحَمَّدًا صلى الله عليه وسلم فَقَالُوا إِنَّ الَّذِي تَقُولُ وَتَدْعُو لَحَسَنٌ وَلَوْ تُخْبِرُنَا أَنَّ لِمَا عَمِلْنَا كَفَّارَةً فَنَزَلَ ‏{‏ وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَلاَ يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا‏}‏ وَنَزَلَ ‏{‏ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لاَ تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ‏{‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 3023c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-3023c","x":"Sa'id b. Jubair reported:\n\n'Abd al Rahman b. Abzi commanded me that I should ask Ibn 'Abbas about these two verses:\" He who slays a believer intentionally his requital shall be Hell where he would abide for ever\" (iv. 92). So, I asked him and he said: Nothing has abrogated it. And as for this verse:\" And they who call not upon another god with Allah and slay not the soul which Allah has forbidden, except in the cause of justice\" (xxv. 68), he (Ibn Abbas) said: This has been revealed in regard to the polytheists.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، وَمُحَمَّدُ بْنُ بَشَّارٍ، قَالاَ حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، عَنْ مَنْصُورٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ أَمَرَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبْزَى أَنْ أَسْأَلَ ابْنَ عَبَّاسٍ، عَنْ هَاتَيْنِ الآيَتَيْنِ، ‏{‏ وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا‏}‏ فَسَأَلْتُهُ فَقَالَ لَمْ يَنْسَخْهَا شَىْءٌ ‏.‏ وَعَنْ هَذِهِ الآيَةِ ‏{‏ وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ‏}‏ قَالَ نَزَلَتْ فِي أَهْلِ الشِّرْكِ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3183","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3183","x":"Narrated 'Abdullah:\n\n\"I asked the Messenger of Allah (ﷺ) which sin is the worst.' He said: 'That you make an equal to Allah while it is He who created you, that you kill your child so that he not eat with you - or because of your food, that you commit adultery with your neighbor's wife.'\" He said: \"And he recited this Ayah: 'And those who invoke not any other god along with Allah, nor kill such life as Allah has forbidden, except for what is required, nor commit illegal sexual intercourse - and whoever does that shall receive punishment. The torment will be doubled for him on the Day of Resurrection, and he will abide therein in disgrace (25:68 & 69).'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا سَعِيدُ بْنُ الرَّبِيعِ أَبُو زَيْدٍ، حَدَّثَنَا شُعْبَةُ، عَنْ وَاصِلٍ الأَحْدَبِ، عَنْ أَبِي وَائِلٍ، عَنْ عَبْدِ اللَّهِ، قَالَ سَأَلْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم أَىُّ الذَّنْبِ أَعْظَمُ قَالَ ‏\"‏ أَنْ تَجْعَلَ لِلَّهِ نِدًّا وَهُوَ خَلَقَكَ وَأَنْ تَقْتُلَ وَلَدَكَ مِنْ أَجْلِ أَنْ يَأْكُلَ مَعَكَ أَوْ مِنْ طَعَامِكَ وَأَنْ تَزْنِيَ بِحَلِيلَةِ جَارِكَ ‏\"‏ ‏.‏ قَالَ وَتَلاَ هَذِهِ الآيَةَ ‏:‏ ‏(‏والَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَلاَ يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا * يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ سُفْيَانَ عَنْ مَنْصُورٍ وَالأَعْمَشِ أَصَحُّ مِنْ حَدِيثِ شُعْبَةَ عَنْ وَاصِلٍ لأَنَّهُ زَادَ فِي إِسْنَادِهِ رَجُلاً ‏.‏ حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، عَنْ شُعْبَةَ، عَنْ وَاصِلٍ، عَنْ أَبِي وَائِلٍ، عَنْ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَهُ ‏.‏ قَالَ وَهَكَذَا رَوَى شُعْبَةُ عَنْ وَاصِلٍ عَنْ أَبِي وَائِلٍ عَنْ عَبْدِ اللَّهِ وَلَمْ يَذْكُرْ فِيهِ عَمْرَو بْنَ شُرَحْبِيلَ ‏.‏","v":[]}],"69":[{"c":"Sahih Bukhari","r":"Hadith 4765","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4765","x":"Narrated Sa`id bin Jubair:\n\nIbn Abza said to me, \"Ask Ibn `Abbas regarding the Statement of Allah: 'And whoever murders a believer intentionally, his recompense is Hell.' (4.69) And also His Statement: '...nor kill such life as Allah has forbidden, except for a just cause.....except those who repent, believe, and do good deeds.' \" (25.68-70) So I asked Ibn `Abbas and he said, \"When this (25.68-69) was revealed, the people of Mecca said, \"We have invoked other gods with Allah, and we have murdered such lives which Allah has made sacred, and we have committed illegal sexual intercourse. So Allah revealed: 'Except those who repent, believe, and do good deeds and Allah is Oft-Forgiving, Most Merciful.' (25.70)","ar":"حَدَّثَنَا سَعْدُ بْنُ حَفْصٍ، حَدَّثَنَا شَيْبَانُ، عَنْ مَنْصُورٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ قَالَ ابْنُ أَبْزَى سَلِ ابْنَ عَبَّاسٍ عَنْ قَوْلِهِ تَعَالَى ‏{‏وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ‏}‏ وَقَوْلِهِ ‏{‏لاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ‏}‏ حَتَّى بَلَغَ ‏{‏إِلاَّ مَنْ تَابَ‏}‏ فَسَأَلْتُهُ فَقَالَ لَمَّا نَزَلَتْ قَالَ أَهْلُ مَكَّةَ فَقَدْ عَدَلْنَا بِاللَّهِ وَقَتَلْنَا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَأَتَيْنَا الْفَوَاحِشَ، فَأَنْزَلَ اللَّهُ ‏{‏إِلاَّ مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلاً صَالِحًا‏}‏ إِلَى قَوْلِهِ ‏{‏غَفُورًا رَحِيمًا‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 122","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-122","x":"It is narrated on the authority of Ibn 'Abbas that some persons amongst the polytheist had committed a large number of murders and had excessively indulged in fornication. Then they came to Muhammad (ﷺ) and said:\n\nWhatever you assert and whatever you call to is indeed good. But if you inform us that there is atonement of our past deeds (then we would embrace Islam). Then it was revealed: And those who call not unto another god along with Allah and slay not any soul which Allah has forbidden except in the cause of justice, nor commit fornication; and he who does this shall meet the requital of sin. Multiplied for him shall be the torment on the Day of Resurrection, and he shall therein abide disgraced, except him who repents a believes and does good deeds. Then these! for the Allah shall change their vices into virtues. Verily Allah is Ever Forgiving, Merciful (xxv. 68-70). Say thou: O my bondsmen woo have committed extravagance against themselves despair not of the Mercy of Allah I Verily Allah will forgive the sins altogether. He is indeed the Forgiving, the Merciful (xxxix. 53).","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمِ بْنِ مَيْمُونٍ، وَإِبْرَاهِيمُ بْنُ دِينَارٍ، - وَاللَّفْظُ لإِبْرَاهِيمَ - قَالاَ حَدَّثَنَا حَجَّاجٌ، - وَهُوَ ابْنُ مُحَمَّدٍ - عَنِ ابْنِ جُرَيْجٍ، قَالَ أَخْبَرَنِي يَعْلَى بْنُ مُسْلِمٍ، أَنَّهُ سَمِعَ سَعِيدَ بْنَ جُبَيْرٍ، يُحَدِّثُ عَنِ ابْنِ عَبَّاسٍ، أَنَّ نَاسًا، مِنْ أَهْلِ الشِّرْكِ قَتَلُوا فَأَكْثَرُوا وَزَنَوْا فَأَكْثَرُوا ثُمَّ أَتَوْا مُحَمَّدًا صلى الله عليه وسلم فَقَالُوا إِنَّ الَّذِي تَقُولُ وَتَدْعُو لَحَسَنٌ وَلَوْ تُخْبِرُنَا أَنَّ لِمَا عَمِلْنَا كَفَّارَةً فَنَزَلَ ‏{‏ وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَلاَ يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا‏}‏ وَنَزَلَ ‏{‏ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لاَ تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ‏{‏ ‏.‏","v":[]}],"70":[{"c":"Sunan Abu Dawud","r":"Hadith 4286","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4286","x":"Narrated Umm Salamah, Ummul Mu'minin:\n\nThe Prophet (ﷺ) said: Disagreement will occur at the death of a caliph and a man of the people of Medina will come flying forth to Mecca. Some of the people of Mecca will come to him, bring him out against his will and swear allegiance to him between the Corner and the Maqam. An expeditionary force will then be sent against him from Syria but will be swallowed up in the desert between Mecca and Medina. When the people see that, the eminent saints of Syria and the best people of Iraq will come to him and swear allegiance to him between the Corner and the Maqam. Then there will arise a man of Quraysh whose maternal uncles belong to Kalb and send against them an expeditionary force which will be overcome by them, and that is the expedition of Kalb. Disappointed will be the one who does not receive the booty of Kalb. He will divide the property, and will govern the people by the Sunnah of their Prophet (ﷺ) and establish Islam on Earth. He will remain seven years, then die, and the Muslims will pray over him. Abu Dawud said: Some transmitted from Hisham \"nine years\" and some \"seven years\".","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا مُعَاذُ بْنُ هِشَامٍ، حَدَّثَنِي أَبِي، عَنْ قَتَادَةَ، عَنْ صَالِحٍ أَبِي الْخَلِيلِ، عَنْ صَاحِبٍ، لَهُ عَنْ أُمِّ سَلَمَةَ، زَوْجِ النَّبِيِّ صلى الله عليه وسلم عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ يَكُونُ اخْتِلاَفٌ عِنْدَ مَوْتِ خَلِيفَةٍ فَيَخْرُجُ رَجُلٌ مِنْ أَهْلِ الْمَدِينَةِ هَارِبًا إِلَى مَكَّةَ فَيَأْتِيهِ نَاسٌ مِنْ أَهْلِ مَكَّةَ فَيُخْرِجُونَهُ وَهُوَ كَارِهٌ فَيُبَايِعُونَهُ بَيْنَ الرُّكْنِ وَالْمَقَامِ وَيُبْعَثُ إِلَيْهِ بَعْثٌ مِنَ الشَّامِ فَيُخْسَفُ بِهِمْ بِالْبَيْدَاءِ بَيْنَ مَكَّةَ وَالْمَدِينَةِ فَإِذَا رَأَى النَّاسُ ذَلِكَ أَتَاهُ أَبْدَالُ الشَّامِ وَعَصَائِبُ أَهْلِ الْعِرَاقِ فَيُبَايِعُونَهُ بَيْنَ الرُّكْنِ وَالْمَقَامِ ثُمَّ يَنْشَأُ رَجُلٌ مِنْ قُرَيْشٍ أَخْوَالُهُ كَلْبٌ فَيَبْعَثُ إِلَيْهِمْ بَعْثًا فَيَظْهَرُونَ عَلَيْهِمْ وَذَلِكَ بَعْثُ كَلْبٍ وَالْخَيْبَةُ لِمَنْ لَمْ يَشْهَدْ غَنِيمَةَ كَلْبٍ فَيَقْسِمُ الْمَالَ وَيَعْمَلُ فِي النَّاسِ بِسُنَّةِ نَبِيِّهِمْ صلى الله عليه وسلم وَيُلْقِي الإِسْلاَمُ بِجِرَانِهِ إِلَى الأَرْضِ فَيَلْبَثُ سَبْعَ سِنِينَ ثُمَّ يُتَوَفَّى وَيُصَلِّي عَلَيْهِ الْمُسْلِمُونَ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ قَالَ بَعْضُهُمْ عَنْ هِشَامٍ ‏\"‏ تِسْعَ سِنِينَ ‏\"‏ ‏.‏ وَقَالَ بَعْضُهُمْ ‏\"‏ سَبْعَ سِنِينَ ‏\"‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3855","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3855","x":"Narrated Sa`id bin Jubair:\n\n`AbdurRahman bin Abza said, \"Ask Ibn `Abbas about these two Qur'anic Verses: 'Nor kill such life as Allah has made sacred, Except for just cause.' (25.68) \"And whoever kills a believer intentionally, his recompense is Hell. (4.93) So I asked Ibn `Abbas who said, \"When the Verse that is in Sura-al-Furqan was revealed, the pagans of Mecca said, 'But we have slain such life as Allah has made sacred, and we have invoked other gods along with Allah, and we have also committed fornication.' So Allah revealed:-- 'Except those who repent, believe, and do good-- (25.70) So this Verse was concerned with those people. As for the Verse in Surat-an-Nisa (4-93), it means that if a man, after understanding Islam and its laws and obligations, murders somebody, then his punishment is to dwell in the (Hell) Fire forever.\" Then I mentioned this to Mujahid who said, \"Except the one who regrets (one's crime). \"","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، حَدَّثَنِي سَعِيدُ بْنُ جُبَيْرٍ، أَوْ قَالَ حَدَّثَنِي الْحَكَمُ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ أَمَرَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبْزَى قَالَ سَلِ ابْنَ عَبَّاسٍ عَنْ هَاتَيْنِ الآيَتَيْنِ، مَا أَمْرُهُمَا ‏{‏وَلاَ تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ ‏}‏ ‏{‏وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا‏}‏ فَسَأَلْتُ ابْنَ عَبَّاسٍ فَقَالَ لَمَّا أُنْزِلَتِ الَّتِي فِي الْفُرْقَانِ قَالَ مُشْرِكُو أَهْلِ مَكَّةَ فَقَدْ قَتَلْنَا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ، وَدَعَوْنَا مَعَ اللَّهِ إِلَهًا آخَرَ، وَقَدْ أَتَيْنَا الْفَوَاحِشَ‏.‏ فَأَنْزَلَ اللَّهُ ‏{‏إِلاَّ مَنْ تَابَ وَآمَنَ‏}‏ الآيَةَ فَهَذِهِ لأُولَئِكَ وَأَمَّا الَّتِي فِي النِّسَاءِ الرَّجُلُ إِذَا عَرَفَ الإِسْلاَمَ وَشَرَائِعَهُ، ثُمَّ قَتَلَ فَجَزَاؤُهُ جَهَنَّمُ‏.‏ فَذَكَرْتُهُ لِمُجَاهِدٍ فَقَالَ إِلاَّ مَنْ نَدِمَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4765","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4765","x":"Narrated Sa`id bin Jubair:\n\nIbn Abza said to me, \"Ask Ibn `Abbas regarding the Statement of Allah: 'And whoever murders a believer intentionally, his recompense is Hell.' (4.69) And also His Statement: '...nor kill such life as Allah has forbidden, except for a just cause.....except those who repent, believe, and do good deeds.' \" (25.68-70) So I asked Ibn `Abbas and he said, \"When this (25.68-69) was revealed, the people of Mecca said, \"We have invoked other gods with Allah, and we have murdered such lives which Allah has made sacred, and we have committed illegal sexual intercourse. So Allah revealed: 'Except those who repent, believe, and do good deeds and Allah is Oft-Forgiving, Most Merciful.' (25.70)","ar":"حَدَّثَنَا سَعْدُ بْنُ حَفْصٍ، حَدَّثَنَا شَيْبَانُ، عَنْ مَنْصُورٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ قَالَ ابْنُ أَبْزَى سَلِ ابْنَ عَبَّاسٍ عَنْ قَوْلِهِ تَعَالَى ‏{‏وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ‏}‏ وَقَوْلِهِ ‏{‏لاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ‏}‏ حَتَّى بَلَغَ ‏{‏إِلاَّ مَنْ تَابَ‏}‏ فَسَأَلْتُهُ فَقَالَ لَمَّا نَزَلَتْ قَالَ أَهْلُ مَكَّةَ فَقَدْ عَدَلْنَا بِاللَّهِ وَقَتَلْنَا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَأَتَيْنَا الْفَوَاحِشَ، فَأَنْزَلَ اللَّهُ ‏{‏إِلاَّ مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلاً صَالِحًا‏}‏ إِلَى قَوْلِهِ ‏{‏غَفُورًا رَحِيمًا‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 122","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-122","x":"It is narrated on the authority of Ibn 'Abbas that some persons amongst the polytheist had committed a large number of murders and had excessively indulged in fornication. Then they came to Muhammad (ﷺ) and said:\n\nWhatever you assert and whatever you call to is indeed good. But if you inform us that there is atonement of our past deeds (then we would embrace Islam). Then it was revealed: And those who call not unto another god along with Allah and slay not any soul which Allah has forbidden except in the cause of justice, nor commit fornication; and he who does this shall meet the requital of sin. Multiplied for him shall be the torment on the Day of Resurrection, and he shall therein abide disgraced, except him who repents a believes and does good deeds. Then these! for the Allah shall change their vices into virtues. Verily Allah is Ever Forgiving, Merciful (xxv. 68-70). Say thou: O my bondsmen woo have committed extravagance against themselves despair not of the Mercy of Allah I Verily Allah will forgive the sins altogether. He is indeed the Forgiving, the Merciful (xxxix. 53).","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمِ بْنِ مَيْمُونٍ، وَإِبْرَاهِيمُ بْنُ دِينَارٍ، - وَاللَّفْظُ لإِبْرَاهِيمَ - قَالاَ حَدَّثَنَا حَجَّاجٌ، - وَهُوَ ابْنُ مُحَمَّدٍ - عَنِ ابْنِ جُرَيْجٍ، قَالَ أَخْبَرَنِي يَعْلَى بْنُ مُسْلِمٍ، أَنَّهُ سَمِعَ سَعِيدَ بْنَ جُبَيْرٍ، يُحَدِّثُ عَنِ ابْنِ عَبَّاسٍ، أَنَّ نَاسًا، مِنْ أَهْلِ الشِّرْكِ قَتَلُوا فَأَكْثَرُوا وَزَنَوْا فَأَكْثَرُوا ثُمَّ أَتَوْا مُحَمَّدًا صلى الله عليه وسلم فَقَالُوا إِنَّ الَّذِي تَقُولُ وَتَدْعُو لَحَسَنٌ وَلَوْ تُخْبِرُنَا أَنَّ لِمَا عَمِلْنَا كَفَّارَةً فَنَزَلَ ‏{‏ وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَلاَ يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا‏}‏ وَنَزَلَ ‏{‏ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لاَ تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ‏{‏ ‏.‏","v":[]}],"74":[{"c":"Al-Adab Al-Mufrad","r":"Book 5, Hadith 87","u":"https://quranx.com/Hadith/Adab/English/Book-5/Hadith-87","x":"Jubayr ibn Nufayr said, \"One day we were sitting when al-Miqdad ibn al-Aswad when a man passed us. The man said, 'Blessing be to those two eyes which saw the Messenger of Allah, may Allah bless him and grant him peace. By Allah, I wish that I had seen what you have seen and witnessed what you have witnessed!' This angered al-Miqdad and that surprised me as the man had said nothing but good things. Then he turned to them and said, 'What made the man desire to summon back what Allah has taken away? Does he not realise what his situation would be if he had seen him? By Allah, if certain people had been with the Messenger of Allah, may Allah bless him and grant him peace, Allah would have thrown them on their faces into Hellfire since they would neither have answered nor confirmed him? Do you not praise Allah Almighty since He brought you forth and you only know your Lord and confirm what your Prophet, may Allah bless him and grant him peace, brought? You see enough affliction in other people. By Allah, the Messenger of Allah, may Allah bless him and grant him peace, was sent in the harshest state in which any Prophet was ever sent - in a gap (in the line of prophethood) and the time of Ignorance. They did not believe that the deen was better than worshipping idols. He brought the Discrimination by which it is possible to discriminate between the true and false, and which can part a father from his child. Then a man will think of his father, child or brother as an unbeliever. Allah has loosened the locks of his heart by faith and he knows that the other person will be destroyed in the Fire. Therefore his eye is not cool since he knows that the one he loves will be in the Fire. It is what Allah says, \"Those who say, 'Our Lord, give us joy in our wives and children.\" (25:74)'\"","ar":"حَدَّثَنَا بِشْرُ بْنُ مُحَمَّدٍ، قَالَ‏:‏ أَخْبَرَنَا عَبْدُ اللهِ، قَالَ‏:‏ أَخْبَرَنَا صَفْوَانُ بْنُ عَمْرٍو قَالَ‏:‏ حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ جُبَيْرِ بْنِ نُفَيْرٍ، عَنْ أَبِيهِ قَالَ‏:‏ جَلَسْنَا إِلَى الْمِقْدَادِ بْنِ الأَسْوَدِ يَوْمًا، فَمَرَّ بِهِ رَجُلٌ فَقَالَ‏:‏ طُوبَى لِهَاتَيْنِ الْعَيْنَيْنِ اللَّتَيْنِ رَأَتَا رَسُولَ اللهِ صلى الله عليه وسلم، وَاللَّهِ لَوَدِدْنَا أَنَّا رَأَيْنَا مَا رَأَيْتَ، وَشَهِدْنَا مَا شَهِدْتَ‏.‏ فَاسْتُغْضِبَ، فَجَعَلْتُ أَعْجَبُ، مَا قَالَ إِلاَّ خَيْرًا، ثُمَّ أَقْبَلَ عَلَيْهِ فَقَالَ‏:‏ مَا يَحْمِلُ الرَّجُلُ عَلَى أَنْ يَتَمَنَّى مُحْضَرًا غَيَّبَهُ اللَّهُ عَنْهُ‏؟‏ لاَ يَدْرِي لَوْ شَهِدَهُ كَيْفَ يَكُونُ فِيهِ‏؟‏ وَاللَّهِ، لَقَدْ حَضَرَ رَسُولَ اللهِ صلى الله عليه وسلم أَقْوَامٌ كَبَّهُمُ اللَّهُ عَلَى مَنَاخِرِهِمْ فِي جَهَنَّمَ، لَمْ يُجِيبُوهُ وَلَمْ يُصَدِّقُوهُ، أَوَلاَ تَحْمَدُونَ اللَّهَ عَزَّ وَجَلَّ إِذْ أَخْرَجَكُمْ لاَ تَعْرِفُونَ إِلاَّ رَبَّكُمْ، فَتُصَدِّقُونَ بِمَا جَاءَ بِهِ نَبِيُّكُمْ صلى الله عليه وسلم، قَدْ كُفِيتُمُ الْبَلاَءَ بِغَيْرِكُمْ، وَاللَّهِ لَقَدْ بُعِثَ النَّبِيُّ صلى الله عليه وسلم عَلَى أَشَدِّ حَالٍ بُعِثَ عَلَيْهَا نَبِيٌّ قَطُّ، فِي فَتْرَةٍ وَجَاهِلِيَّةٍ، مَا يَرَوْنَ أَنَّ دِينًا أَفْضَلُ مِنْ عِبَادَةِ الأَوْثَانِ، فَجَاءَ بِفُرْقَانٍ فَرَّقَ بِهِ بَيْنَ الْحَقِّ وَالْبَاطِلِ، وَفَرَّقَ بِهِ بَيْنَ الْوَالِدِ وَوَلَدِهِ، حَتَّى إِنْ كَانَ الرَّجُلُ لَيَرَى وَالِدَهُ أَوْ وَلَدَهُ أَوْ أَخَاهُ كَافِرًا، وَقَدْ فَتْحَ اللَّهُ قُفْلَ قَلْبِهِ بِالإِيمَانِ، وَيَعْلَمُ أَنَّهُ إِنْ هَلَكَ دَخَلَ النَّارَ، فَلاَ تَقَرُّ عَيْنُهُ، وَهُوَ يَعْلَمُ أَنَّ حَبِيبَهُ فِي النَّارِ، وَأنَّهَا لِلَّتِي قَالَ اللَّهُ عَزَّ وَجَلَّ‏:‏ ‏{‏وَالَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ‏}‏‏.‏","v":[]}],"77":[{"c":"Sahih Bukhari","r":"Hadith 4767","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4767","x":"Narrated `Abdullah:\n\nFive (great events) have passed: the Smoke, the Moon, the Romans, the Mighty grasp and the constant Punishment which occurs in 'So the torment will be yours forever.' (25.77)","ar":"حَدَّثَنَا عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الأَعْمَشُ، حَدَّثَنَا مُسْلِمٌ، عَنْ مَسْرُوقٍ، قَالَ قَالَ عَبْدُ اللَّهِ خَمْسٌ قَدْ مَضَيْنَ الدُّخَانُ وَالْقَمَرُ وَالرُّومُ وَالْبَطْشَةُ وَاللِّزَامُ ‏{‏فَسَوْفَ يَكُونُ لِزَامًا‏}‏","v":[]}]};